      "name": "MvPolynomial.optionEquivRight_apply",
      "type": " (R : Type u) (S₁ : Type v) [CommSemiring R] (a : MvPolynomial (Option S₁) R) : (MvPolynomial.optionEquivRight R S₁) a = (MvPolynomial.aeval fun o => o.elim (MvPolynomial.C Polynomial.X) MvPolynomial.X) a",
      "module": "Mathlib.Algebra.MvPolynomial.Equiv"
    },
    {
      "name": "MvPolynomial.optionEquivLeft_apply",
      "type": " (R : Type u) (S₁ : Type v) [CommSemiring R] (a : MvPolynomial (Option S₁) R) : (MvPolynomial.optionEquivLeft R S₁) a = (MvPolynomial.aeval fun o => o.elim Polynomial.X fun s => Polynomial.C (MvPolynomial.X s)) a",
      "module": "Mathlib.Algebra.MvPolynomial.Equiv"
    },
    {
      "name": "AlgebraicIndependent.mvPolynomialOptionEquivPolynomialAdjoin_apply",
      "type": " {ι : Type u} {R : Type u_2} {A : Type v} {x : ι → A} [CommRing R] [CommRing A] [Algebra R A] (hx : AlgebraicIndependent R x) (y : MvPolynomial (Option ι) R) : hx.mvPolynomialOptionEquivPolynomialAdjoin y = Polynomial.map (↑hx.aevalEquiv) ((MvPolynomial.aeval fun o => o.elim Polynomial.X fun s => Polynomial.C (MvPolynomial.X s)) y)",
      "module": "Mathlib.RingTheory.AlgebraicIndependent.Basic"
    },
    {
      "name": "Polynomial.aeval_homogenize_X_one",
      "type": " {R : Type u_1} [CommSemiring R] (p : Polynomial R) {n : ℕ} (hn : p.natDegree ≤ n) : (MvPolynomial.aeval ![Polynomial.X, 1]) (p.homogenize n) = p",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    },
    {
      "name": "Polynomial.homogenize_eq_of_isHomogeneous",
      "type": " {R : Type u_1} [CommSemiring R] {p : Polynomial R} {n : ℕ} {q : MvPolynomial (Fin 2) R} (hq : q.IsHomogeneous n) (hpq : (MvPolynomial.aeval ![Polynomial.X, 1]) q = p) : p.homogenize n = q",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    },
    {
      "name": "Polynomial.eval_X_toTupleMvPolynomial_zero_eq",
      "type": " {R : Type u_1} [CommSemiring R] (p : Polynomial R) : (MvPolynomial.aeval ![Polynomial.X, 1]) (p.toTupleMvPolynomial 0) = p * (MvPolynomial.aeval ![Polynomial.X, 1]) (p.toTupleMvPolynomial 1)",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    }
  ]
